<script setup lang="ts">
import type {DhcpInterface,DhcpResult} from '../tools/dhcp'
const p=defineProps<{en:boolean;data:DhcpResult|null;error?:{code:string;message:string}}>(),emit=defineEmits<{choose:[id:string]}>(),t=(a:string,b:string)=>p.en?b:a
const unknown=(v:unknown)=>v==null||v===''?t('未知','unknown'):v
const fields=(i:DhcpInterface)=>[[t('配置来源','Configuration source'),i.config_source],[t('MAC','MAC'),i.mac],[t('DHCP 已启用','DHCP enabled'),i.dhcp_enabled==null?null:i.dhcp_enabled?t('是','yes'):t('否','no')],[t('服务器','Server'),i.server],[t('租约开始 / 到期','Lease start / expiry'),`${unknown(i.lease_start)} / ${unknown(i.lease_expires)}`],[t('地址 / 掩码','Address / mask'),i.addresses.map(a=>`${a.address} / ${a.mask}`).join('; ')],[t('网关','Gateways'),i.gateways.join(', ')],['DNS',i.dns.join(', ')],[t('搜索域','Search domains'),i.search_domains.join(', ')]]
</script>
<template><div class="dhcp-results"><template v-if="data"><h3>{{t('DHCPv4 观测','DHCPv4 observations')}} · {{data.diagnostic_outcome}}</h3>
<p>{{data.started_at}} · {{data.duration_ms}} ms · {{data.partial?t('部分结果','Partial results'):t('收集完成','Collection complete')}}</p>
<p class="dhcp-counters">DISCOVER {{data.stats.sent}} · {{t('收到','Received')}} {{data.stats.received}} · {{t('忽略 / 畸形 / 重复 / 超预算','Ignored / malformed / duplicates / dropped')}} {{data.stats.ignored}} / {{data.stats.malformed}} / {{data.stats.duplicates}} / {{data.stats.offers_dropped}}</p>
<p v-if="data.operation==='discover'">{{t('本地绑定','Local bind')}} {{data.local_endpoint}} → {{data.remote_endpoint}} · xid {{data.transaction_id}} · {{data.client_mac}}</p>
<article v-for="i in data.interfaces" :key="i.id" class="dhcp-interface"><h4>{{i.name}} [{{i.index}}]</h4><p>{{i.id}}</p><dl><template v-for="[key,value] in fields(i)" :key="String(key)"><dt>{{key}}</dt><dd>{{unknown(value)}}</dd></template></dl>
<button class="dhcp-handoff" @click="emit('choose',i.id)">{{t('用此接口预填主动发现','Use interface for discovery')}}</button><details><summary>{{t('字段来源与限制','Field sources and limitations')}}</summary><p v-for="(v,k) in i.field_sources" :key="k">{{k}}: {{v}}</p><p v-for="l in i.limitations" :key="l">{{l}}</p></details></article>
<div v-if="data.offers.length" class="table-scroll"><table class="dhcp-table"><thead><tr><th>{{t('服务器 / 报文来源','Server / packet source')}}</th><th>yiaddr / {{t('租期','lease')}}</th><th>{{t('掩码 / 路由 / DNS','Mask / routers / DNS')}}</th><th>{{t('Relay / 清单比较','Relay / expected list')}}</th></tr></thead><tbody><tr v-for="(o,n) in data.offers" :key="n"><td>{{o.server_id}}<br>{{o.packet_source}}<br>{{o.observed_at}}</td><td>{{o.yiaddr}}<br>{{unknown(o.lease_secs)}} s<br>siaddr: {{o.siaddr}}</td><td>{{unknown(o.mask)}}<br>{{o.routers.join(', ')}}<br>{{o.dns.join(', ')}}<br>{{o.search_domains.join(', ')}}</td><td>{{o.relay}}<br>{{unknown(o.relay_agent_hex)}}<br>{{o.outside_expected===null?t('未提供清单','No expected list'):o.outside_expected?t('清单外服务器','Outside expected list'):t('在预期清单中','In expected list')}}</td></tr></tbody></table></div>
<p v-else-if="data.operation==='discover'">{{t('窗口内尚无匹配 Offer；这不证明网络没有 DHCP 服务器。','No matching offer observed in this window; this does not prove there is no DHCP server.')}}</p>
<details open><summary>{{t('能力与限制','Capabilities and limitations')}}</summary><p v-for="l in data.limitations" :key="l">{{l}}</p></details></template><p v-if="error" class="result-error">{{error.code}} · {{error.message}}</p></div></template>
<style scoped>.dhcp-results{min-width:0;padding:20px;box-sizing:border-box;overflow-wrap:anywhere}.dhcp-interface{padding:12px 0;border-bottom:1px solid var(--border)}dl{display:grid;grid-template-columns:minmax(90px,1fr) minmax(0,3fr);gap:6px}dt{font-weight:600}dd{margin:0}.dhcp-table{min-width:580px}.dhcp-table th,.dhcp-table td{white-space:normal}</style>
